import { jsPDF } from "jspdf"
var font = '';
var callAddFont = function () {
this.addFileToVFS('NotoSansTamil_Condensed-Regular-normal.ttf', font);
this.addFont('NotoSansTamil_Condensed-Regular-normal.ttf', 'NotoSansTamil_Condensed-Regular', 'normal');
};
jsPDF.API.events.push(['addFonts', callAddFont])
